+package main
+
+import (
+    "fmt"
+    "github.com/Masterminds/squirrel"
+)
+
+func main() {
+    // This should generate: INSERT INTO test VALUES (?)
+    // But actually generates: INSERT INTO est VALUES (?)
+    sql, _, _ := squirrel.Insert("test").Values("value").ToSql()
+    fmt.Println("Expected: INSERT INTO test VALUES (?)")
+    fmt.Println("Actual:  ", sql)
+    
+    // Another example with "table"
+    sql2, _, _ := squirrel.Insert("table").Columns("field1").Values("value1").ToSql()
+    fmt.Println("Expected: INSERT INTO table (field1) VALUES (?)")
+    fmt.Println("Actual:  ", sql2)
+}

